for (const [name, contents, mode, diagnostic] of [
  ["noexec", "#!/bin/bash\nsay bad", 0o644, "Permission denied"],
  ["noread", "#!/bin/bash\nsay bad", 0o111, "Permission denied"],
  ["python", "#!/usr/bin/python\nsay bad", 0o755, "unsupported interpreter"],
